System.out.println("=== PRZELEW 200 zl: Konto A -> Konto B (sukces, COMMIT) ===");
conn.setAutoCommit(false);
try {
    stmt.executeUpdate("UPDATE accounts SET balance = balance - 200 WHERE id = 1");
    stmt.executeUpdate("UPDATE accounts SET balance = balance + 200 WHERE id = 2");
    conn.commit();
    System.out.println("Przelew zatwierdzony (COMMIT).");
} catch (SQLException e) {
    conn.rollback();
    System.out.println("Blad - przelew wycofany: " + e.getMessage());
} finally {
    conn.setAutoCommit(true);
}
// setAutoCommit(false) wylacza domyslny tryb, w ktorym KAZDE zapytanie
// jest osobna, natychmiast zatwierdzana transakcja.

System.out.println("=== PRZELEW 2000 zl: Konto A -> Konto B (blad, ROLLBACK) ===");
conn.setAutoCommit(false);
try {
    stmt.executeUpdate("UPDATE accounts SET balance = balance + 2000 WHERE id = 2");
    stmt.executeUpdate("UPDATE accounts SET balance = balance - 2000 WHERE id = 1"); // zejdzie ponizej 0 -> CHECK rzuci wyjatek
    conn.commit();
} catch (SQLException e) {
    conn.rollback();
    System.out.println("Blad wykryty - transakcja wycofana (ROLLBACK).");
} finally {
    conn.setAutoCommit(true);
}
// ROLLBACK cofa WSZYSTKIE zmiany od poczatku transakcji - wlacznie z JUZ
// wykonanym dodaniem do konta B, mimo ze to DRUGI UPDATE zawiodl.

conn.setAutoCommit(false);
try {
    stmt.executeUpdate("UPDATE accounts SET balance = balance - 100 WHERE id = 1");
    Savepoint afterFirstStep = conn.setSavepoint("po_odjeciu_od_A");

    try {
        stmt.executeUpdate("UPDATE accounts SET balance = balance - 999999 WHERE id = 2");
    } catch (SQLException e) {
        conn.rollback(afterFirstStep); // cofa TYLKO krok 2, nie caly poczatek
    }

    conn.commit(); // zatwierdza to, co zostalo po cofnieciu do savepointu
} finally {
    conn.setAutoCommit(true);
}
// Krok 1 (odjecie od A) ZOSTAJE zatwierdzony, krok 2 zostaje WYCOFANY.
